package net.officefloor.hq.app.period;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Listing, adding, generating, closing, soft-closing and reopening the periods on a sheet. */
@RestController
@RequestMapping("/api/periods")
public class PeriodController {

    public record ListPeriodsRequest(@NotBlank @Size(max = 100) String sheet) {
    }

    /** A period's name has no spaces: it is written into the audit record as one field. */
    public record AddPeriodRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotBlank @Size(max = 100) @Pattern(regexp = "\\s*\\S+\\s*") String name, @NotNull LocalDate from,
            @NotNull LocalDate to) {
    }

    public record GeneratePeriodsRequest(@NotBlank @Size(max = 100) String sheet,
            @NotBlank @Size(max = 100) String user, @NotNull LocalDate from, @NotNull LocalDate to) {
    }

    public record ClosePeriodRequest(@NotBlank @Size(max = 100) String sheet, @NotBlank @Size(max = 100) String user,
            @NotNull Long id) {
    }

    /**
     * closedDue is the due-total fixed when the period was closed, closedDues each person's (by
     * person id); null while it is open.
     */
    public record PeriodResponse(long id, String name, LocalDate from, LocalDate to, boolean closed,
            boolean softClosed, String closedDue, Map<String, String> closedDues) {
    }

    private static PeriodResponse response(Period period) {
        return new PeriodResponse(period.getId(), period.getName(), period.getFromDate(), period.getToDate(),
                period.isClosed(), period.isSoftClosed(),
                period.getClosedDue() == null ? null
                        : period.getClosedDue().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
                period.isClosed() || period.isSoftClosed() ? closedDues(period) : null);
    }

    private static Map<String, String> closedDues(Period period) {
        Map<String, String> dues = new TreeMap<>();
        period.getClosedDues().forEach((person, due) -> dues.put(String.valueOf(person),
                due.setScale(2, RoundingMode.UNNECESSARY).toPlainString()));
        return dues;
    }

    private final PeriodService service;

    public PeriodController(PeriodService service) {
        this.service = service;
    }

    @PostMapping("/list")
    public List<PeriodResponse> list(@Valid @RequestBody ListPeriodsRequest req) {
        return service.list(req.sheet().trim()).stream().map(PeriodController::response).toList();
    }

    @PostMapping("/add")
    public PeriodResponse add(@Valid @RequestBody AddPeriodRequest req) {
        return response(service.add(req.sheet().trim(), req.user().trim(), req.name().trim(), req.from(), req.to()));
    }

    /** The periods made, by from-date. */
    @PostMapping("/generate")
    public List<PeriodResponse> generate(@Valid @RequestBody GeneratePeriodsRequest req) {
        return service.generate(req.sheet().trim(), req.user().trim(), req.from(), req.to()).stream()
                .map(PeriodController::response).toList();
    }

    @PostMapping("/reopen")
    public PeriodResponse reopen(@Valid @RequestBody ClosePeriodRequest req) {
        return response(service.reopen(req.sheet().trim(), req.user().trim(), req.id()));
    }

    @PostMapping("/soft-close")
    public PeriodResponse softClose(@Valid @RequestBody ClosePeriodRequest req) {
        return response(service.softClose(req.sheet().trim(), req.user().trim(), req.id()));
    }

    @PostMapping("/close")
    public PeriodResponse close(@Valid @RequestBody ClosePeriodRequest req) {
        return response(service.close(req.sheet().trim(), req.user().trim(), req.id()));
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.role.RoleService;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The sheet's periods: added on the screen, each a name unique on the sheet (without regard to
 * case) and a from and to date, both inclusive; no two periods on a sheet overlap. A period can be
 * closed once: closing fixes its due-total at that moment, and no claim whose due-by is inside a
 * closed period can be added, edited, opened, settled or voided. A steward can reopen a closed period, which
 * makes its due-total live again. A period can instead be soft-closed: its figures are fixed in the
 * same way but its claims can still change; it can then be closed (fixing them afresh) or reopened. With grace days set, a change of the sheet's today closes the
 * periods past them (see {@link SheetService#setToday}).
 */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetService sheets;
    private final SheetRepository sheetRows;
    private final Audit audit;
    private final RoleService roles;

    public PeriodService(PeriodRepository periods, SheetService sheets, SheetRepository sheetRows, Audit audit,
            RoleService roles) {
        this.roles = roles;
        this.periods = periods;
        this.sheets = sheets;
        this.sheetRows = sheetRows;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromDateAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        roles.refuseViewer(sheetId, user);
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId, user);
        // hold the sheet so two periods added at the same moment are checked one after the other
        sheetRows.findLockedById(sheetId);
        if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
        }
        if (periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, to, from)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
        }
        Period added;
        try {
            added = periods.saveAndFlush(new Period(sheetId, name, from, to));
        } catch (DataIntegrityViolationException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period name is already in use on this sheet.");
        }
        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + user + " period=" + added.getName() + " from="
                + added.getFromDate() + " to=" + added.getToDate());
        return added;
    }

    /**
     * Generate one period per calendar month from the from-date's month to the to-date's month, each
     * running from the first to the last day of its month and named yyyy-mm. A month whose name is
     * already a period, or whose days overlap a period on the sheet, is left out; the others are
     * still made. Refused (400) when the to-date is before the from-date.
     */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        roles.refuseViewer(sheetId, user);
        if (to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
        }
        sheets.load(sheetId, user);
        // hold the sheet so periods added at the same moment are checked one after the other
        sheetRows.findLockedById(sheetId);
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            if (periods.existsBySheetIdAndNameIgnoreCase(sheetId, name)
                    || periods.existsBySheetIdAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, last, first)) {
                continue;
            }
            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
