          proofThresholdBFrom: from['proof-threshold-B'] ?? null,
          proofThresholdCFrom: from['proof-threshold-C'] ?? null,
          pot,
          parent,
        }),
      );
      if (this.session.sheet() !== sheet) return;
      this.show(res);
      this.limitInput.set(null);
